// ---- story (chapter Ch8 part 8b, ch8b agent 2026-10-07: Sapphire data/maps/Route123_BerryMastersHouse/scripts.inc;
// generators keep everything from this line on)
// The Berry Master (uid 1) hands out two random Berries a day (Pomeg ... Nomel); his wife (uid 2) asks for a good saying
// (Sapphire: Easy Chat screen type 13; a pair of words from gBerryMasterWifePhrases gives one of five rare Berries once:
// Spelon, Pamtre, Watmel, Durin, Belue; any other pair, a random Cheri ... Nomel Berry). The daily flags are Black 2's
// midnight-reset flags 2750/2751. Sapphire's OnTransition (FLAG_LANDMARK_BERRY_MASTERS_HOUSE) is not needed (landmarks:
// S_optional, the PokeNav). Text lines 1-10 of src/text/script/0338_room_Route123_BerryMastersHouse.txt.
// Black 2's word picker (CallPhraseSelect 4: the quiz's) has Gen 5's vocabulary, not the five phrases (Great Battle,
// Challenge Contest, Overwhelming Latias, Cool Latios, Super Hustle) and returns word ids: the pair's sum modulo 40 stands
// in for "which phrase" (0-4 = one of the five rare Berries, anything else = the common case).
#include "scenes/ch8b_lib.inc"
#define T_MasterIntro 1
#define T_MasterAnother 2
#define T_MasterVisit 3
#define T_MasterDone 4
#define T_WifeAsk 5
#define T_WifeRemarkable 6
#define T_WifeGood 7
#define T_WifeGrand 8
#define T_WifeAh 9
#define T_BagFull 10

Story_BM_Master:                        // Route123_BerryMastersHouse_EventScript_1639E9
    c8b_talk
    h_goto_if_set FLAG_DAILY_RECEIVED_BERRY_FROM_BERRYMASTER, L_BM_MasterDone
    h_msgbox T_MasterIntro              // You may call me the Berry Master. ... You're deserving of one!
    h_closemessage
    Random C8B_A, 10                    // random 10; addvar 20; addvar ITEM_CHERI_BERRY (Sapphire 133)
    WorkAdd C8B_A, ITEM_CHERI_BERRY + 20
    c8b_giveitem_var C8B_A
    h_goto_if_eq HLIB_RESULT, 0, L_BM_BagFull
    h_setflag FLAG_DAILY_RECEIVED_BERRY_FROM_BERRYMASTER
    h_msgbox T_MasterAnother            // Why be stingy? Take another!
    h_closemessage
    Random C8B_A, 10
    WorkAdd C8B_A, ITEM_CHERI_BERRY + 20
    c8b_giveitem_var C8B_A
    h_goto_if_eq HLIB_RESULT, 0, L_BM_BagFull
    h_msgbox T_MasterVisit              // Be sure to visit the Pretty Petal flower shop near Rustboro. ...
    h_release
L_BM_MasterDone:
    h_msgbox T_MasterDone               // I'm done for today. Come again another day. ...
    h_release

Story_BM_Wife:                          // Route123_BerryMastersHouse_EventScript_163A64
    c8b_talk
    h_goto_if_set FLAG_DAILY_RECEIVED_BERRY_FROM_BERRYMASTER_WIFE, L_BM_WifeDone
    h_msgbox T_WifeAsk                  // The way my husband grows Berries, oh, he's the best in the world. ... have you heard a good saying lately?
    c8b_phrase C8B_SEL, C8B_A, C8B_B
    h_goto_if_eq C8B_SEL, 1, L_BM_WifePhrase
    h_msgbox T_WifeAh                   // Ah...
    h_msgbox T_WifeGrand                // Our four grandchildren should become more accomplished than my husband. ...
    h_release
L_BM_WifePhrase:                        // EventScript_163AAD: VAR_0x8004 0-5
    WorkAdd C8B_A, C8B_B
    WorkMod C8B_A, 40
    h_goto_if_eq C8B_A, 0, L_BM_Spelon
    h_goto_if_eq C8B_A, 1, L_BM_Pamtre
    h_goto_if_eq C8B_A, 2, L_BM_Watmel
    h_goto_if_eq C8B_A, 3, L_BM_Durin
    h_goto_if_eq C8B_A, 4, L_BM_Belue
L_BM_Common:                            // EventScript_163AF0: Oh! A good saying it is. You're quite remarkable. I want you to have this.
    h_msgbox T_WifeGood
    h_closemessage
    Random C8B_A, 10
    WorkAdd C8B_A, ITEM_CHERI_BERRY
    c8b_giveitem_var C8B_A
    h_goto_if_eq HLIB_RESULT, 0, L_BM_BagFull
L_BM_WifeGave:                          // EventScript_163C1D
    h_setflag FLAG_DAILY_RECEIVED_BERRY_FROM_BERRYMASTER_WIFE
L_BM_WifeDone:                          // EventScript_163C13 (also said after giving)
    h_msgbox T_WifeGrand
    h_release
L_BM_Spelon:
    h_goto_if_set FLAG_RECEIVED_SPELON_BERRY, L_BM_Common
    h_msgbox T_WifeRemarkable           // Ah! What a remarkable saying! Inspirational, it is! I want you to have this.
    h_closemessage
    h_giveitem ITEM_SPELON_BERRY
    h_goto_if_eq HLIB_RESULT, 0, L_BM_BagFull
    h_setflag FLAG_RECEIVED_SPELON_BERRY
    VMJump L_BM_WifeGave
L_BM_Pamtre:
    h_goto_if_set FLAG_RECEIVED_PAMTRE_BERRY, L_BM_Common
    h_msgbox T_WifeRemarkable
    h_closemessage
    h_giveitem ITEM_PAMTRE_BERRY
    h_goto_if_eq HLIB_RESULT, 0, L_BM_BagFull
    h_setflag FLAG_RECEIVED_PAMTRE_BERRY
    VMJump L_BM_WifeGave
L_BM_Watmel:
    h_goto_if_set FLAG_RECEIVED_WATMEL_BERRY, L_BM_Common
    h_msgbox T_WifeRemarkable
    h_closemessage
    h_giveitem ITEM_WATMEL_BERRY
    h_goto_if_eq HLIB_RESULT, 0, L_BM_BagFull
    h_setflag FLAG_RECEIVED_WATMEL_BERRY
    VMJump L_BM_WifeGave
L_BM_Durin:
    h_goto_if_set FLAG_RECEIVED_DURIN_BERRY, L_BM_Common
    h_msgbox T_WifeRemarkable
    h_closemessage
    h_giveitem ITEM_DURIN_BERRY
    h_goto_if_eq HLIB_RESULT, 0, L_BM_BagFull
    h_setflag FLAG_RECEIVED_DURIN_BERRY
    VMJump L_BM_WifeGave
L_BM_Belue:
    h_goto_if_set FLAG_RECEIVED_BELUE_BERRY, L_BM_Common
    h_msgbox T_WifeRemarkable
    h_closemessage
    h_giveitem ITEM_BELUE_BERRY
    h_goto_if_eq HLIB_RESULT, 0, L_BM_BagFull
    h_setflag FLAG_RECEIVED_BELUE_BERRY
    VMJump L_BM_WifeGave

L_BM_BagFull:
    h_bag_is_full T_BagFull
    h_release
